import shutil, openpyxl, datetime, re
from openpyxl.utils import column_index_from_string

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Edit" in wb.sheetnames:
    ws = wb["Edit"]
    vws = vals["Edit"]
else:
    ws = wb.active
    vws = vals.active

def to_time_fraction(v): ...

start_col = 6
end_col = min(column_index_from_string("AT"), vws.max_column)
time_map = {}
for c in range(start_col, end_col+1):
    f = to_time_fraction(vws.cell(row=1, column=c).value)
    if f is not None:
        time_map[c] = f

# fill missing
if time_map:
    known = sorted(time_map)
    for c in range(start_col, end_col+1):
        if c not in time_map:
            prev = None; nxt = None
            for k in known:
                if k < c: prev = k
                elif k > c:
                    nxt = k; break
            if prev is not None and nxt is not None:
                t0 = time_map[prev]; t1 = time_map[nxt]
                dt = t1 - t0
                if dt < -0.5: dt += 1.0
                elif dt > 0.5: dt -= 1.0
                frac = (c - prev) / (nxt - prev)
                t = t0 + dt * frac
            elif prev is not None:
                # estimate 15 min step
                t = time_map[prev] + (c - prev) * 15/1440
            elif nxt is not None:
                t = time_map[nxt] - (nxt - c) * 15/1440
            else:
                t = 8/24 + (c - start_col) * 15/1440
            time_map[c] = t % 1.0
else:
    for c in range(start_col, end_col+1):
        time_map[c] = (8/24 + (c - start_col) * 15/1440) % 1.0

def is_m(v):
    return v is not None and str(v).strip().lower() == 'm'

last_row = 16
for r in range(2, last_row+1):
    blocks=[]
    in_block=False
    start_c=None
    for c in range(start_col, end_col+1):
        if is_m(vws.cell(row=r, column=c).value):
            if not in_block:
                in_block=True; start_c=c
        else:
            if in_block:
                blocks.append((start_c, c-1))
                in_block=False
    if in_block:
        blocks.append((start_c, end_col))
    out=[None,None,None,None]
    for i,(s,e) in enumerate(blocks[:2]):
        if s in time_map: out[2*i] = time_map[s]
        if e in time_map: out[2*i+1] = time_map[e]
    for j,val in enumerate(out):
        cell = ws.cell(row=r, column=2+j)
        cell.value = val
        if val is not None:
            cell.number_format = 'hh:mm:ss'
    print(r, out)

wb.save(OUT)
